<script setup lang="ts">
import ServerTable from "../../components/ServerTable.vue";
import { Head, Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import QuotationParticipants, { type Participant } from '../../components/QuotationParticipants.vue';
import { rupiah } from '../../composables/costing';
const props = defineProps<{ program: { id: number; nomor: string; judul: string; jenis: string; tgl_mulai: string; tgl_selesai: string; lokasi: string; target_peserta: number; closed_date: string | null }; quotations: { id: number; nomor: string; tanggal: string; berlaku_sampai: string; kepada_nama: string | null; name_customer: string | null; tujuan: string; up_nama: string | null; status: string; terisi: number; kuota_peserta: number; link_closed: string | null; calc: { grand_total: string; n_peserta: number } }[]; peserta: Participant[]; hasParticipants: boolean; dataTab: boolean; filters: Record<string, string>; pesertaStatus: string; canAdd: boolean; canManage: boolean }>();
const f = reactive({ q: '', status: '', tujuan: '', data: props.dataTab ? 1 : 0, peserta_status: props.pesertaStatus, ...props.filters });
const search = () => router.get(`/quotation/batch/${props.program.id}`, f);
</script>
<template>
    <Head :title="program.nomor" /><AppLayout title="Quotation" full-width><div class="page-head"><h1>{{ program.nomor }} · {{ program.judul }}</h1><Link v-if="canAdd && !dataTab" :href="`/quotation/create?id_penjualan=${program.id}`">Buat Quotation</Link></div><p>{{ program.jenis.toUpperCase() }} · {{ program.tgl_mulai }} s.d. {{ program.tgl_selesai }} · {{ program.lokasi }} · Target {{ program.target_peserta }} peserta{{ program.closed_date ? ' · Closed' : '' }}</p><Link href="/quotation">Semua Penjualan Program</Link>
        <nav class="tabs" aria-label="Detail batch"><Link :href="`/quotation/batch/${program.id}`">Quotation</Link><Link :href="`/quotation/batch/${program.id}?data=1`">Data Peserta</Link><a v-if="dataTab && hasParticipants" :href="`/quotation/batch/${program.id}/pdf`" target="_blank" rel="noopener">Export PDF peserta aktif dan surat</a></nav>
        <form class="filters" @submit.prevent="search"><label v-if="dataTab">Status peserta<select v-model="f.peserta_status"><option value="aktif">Aktif</option><option value="menunggu">Menunggu</option><option value="deal">Deal</option><option value="batal">Batal</option><option value="keluar">Keluar</option></select></label><template v-else><label>Status<select v-model="f.status"><option value="">Semua</option><option v-for="s in ['draft', 'terkirim', 'deal', 'batal']" :key="s">{{ s }}</option></select></label><label>Tujuan<select v-model="f.tujuan"><option value="">Semua</option><option value="personal">Personal</option><option value="company">Company</option></select></label></template><button class="primary">Terapkan</button></form>
        <QuotationParticipants v-if="dataTab" :rows="peserta" :data-url="`/quotation/batch/${program.id}/data`" :filters="{ ...filters, data: 1, peserta_status: pesertaStatus }" :manage="canManage && !program.closed_date" />
        <ServerTable :url="`/quotation/batch/${program.id}/data`" label="Quotation per program" :columns='[{"title": "No", "orderable": false}, {"title": "Quotation", "orderable": true}, {"title": "Kepada", "orderable": true}, {"title": "Peserta", "orderable": true}, {"title": "Nilai", "orderable": false}, {"title": "Status", "orderable": true}, {"title": "Action", "orderable": false}]' :filters="{ ...filters }" refresh-on-visit v-else><template #cell-0="{ row: p, number }">{{ number }}</template><template #cell-1="{ row: p, number }">{{ p.nomor }}<small>{{ p.tanggal }} · berlaku s.d. {{ p.berlaku_sampai }}</small></template><template #cell-2="{ row: p, number }">{{ p.name_customer || p.kepada_nama }}<small>{{ p.tujuan }} · {{ p.up_nama }}</small></template><template #cell-3="{ row: p, number }">{{ p.status==='deal'?`${p.calc.n_peserta} peserta Deal`:`${p.terisi} dari kuota ${p.kuota_peserta} terisi` }}</template><template #cell-4="{ row: p, number }">{{ rupiah(p.calc.grand_total) }}</template><template #cell-5="{ row: p, number }">{{ p.status }}<small>{{ p.link_closed || "Link terbuka" }}</small></template><template #cell-6="{ row: p, number }"><Link :href="`/quotation/${p.id}`">Lihat detail</Link><p><Link :href="`/quotation/${p.id}?tab=data`">Data Peserta</Link></p></template></ServerTable>
    </AppLayout>
</template>
